import assert from 'node:assert/strict';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createRequire } from 'node:module';
import { SqliteMemoryRepository } from './packages/storage/src/index.ts';
import { AutomationRuntime } from './packages/automation/src/index.ts';

const require = createRequire(import.meta.url);
const source = require('node:fs').readFileSync('packages/automation/src/index.ts', 'utf8');
assert.match(source, /previousResponseId:\s*null/, 'agentic browser perception must pass null response state');
assert.doesNotMatch(source, /let\s+previousResponseId\s*:/, 'agentic browser loop must not accumulate response state');
assert.doesNotMatch(source, /previousResponseId\s*=\s*decision\.previousResponseId/, 'agentic browser loop must not chain model response ids');

const dir = mkdtempSync(join(tmpdir(), 'ultron-agentic-self-contained-'));
const repo = new SqliteMemoryRepository(join(dir, 'automation.sqlite'));
await repo.migrate();
const captured = [];
const decider = {
  name: 'capture-self-contained-turns',
  async decide(perception) {
    captured.push({
      stepIndex: perception.stepIndex,
      previousResponseId: perception.previousResponseId,
      historyLength: perception.history.length,
      pageText: perception.pageText,
      screenshotBase64: perception.screenshotBase64 ?? null
    });
    if (perception.stepIndex === 1) {
      return { action: { action: 'observe' }, previousResponseId: 'resp-one' };
    }
    if (perception.stepIndex === 2) {
      return { action: { action: 'scroll', direction: 'down' }, previousResponseId: 'resp-two' };
    }
    return { action: { action: 'done', success: true, evidence: 'condition ready' }, previousResponseId: 'resp-three' };
  }
};
