207	func brainSessionsFingerprint(outputDir string) string {
208		manifest, err := loadBrainManifest(outputDir)
209		if err != nil || manifest.Sources == nil || manifest.Sources.Sessions == nil {
210			return ""
211		}
212		return sessionSourceFingerprint(manifest.Sources.Sessions)
