215	func sessionSourceFingerprint(source *sessionSourceManifest) string {
216		if source == nil {
217			return ""
218		}
219		type fingerprintSession struct {
220			SessionID        string `json:"session_id"`
221			LatestCheckpoint string `json:"latest_checkpoint_id"`
222			Branch           string `json:"branch,omitempty"`
223			TranscriptPath   string `json:"transcript_path"`
224		}
225		payload := struct {
226			DefaultBranch      string               `json:"default_branch,omitempty"`
227			TranscriptMode     string               `json:"transcript_mode"`
228			Scope              string               `json:"scope"`
229			LatestCheckpointID string               `json:"latest_checkpoint_id,omitempty"`
230			Sessions           []fingerprintSession `json:"sessions"`
231		}{
232			DefaultBranch:      source.DefaultBranch,
233			TranscriptMode:     source.TranscriptMode,
234			Scope:              source.Scope,
235			LatestCheckpointID: source.LatestCheckpointID,
236			Sessions:           make([]fingerprintSession, 0, len(source.Sessions)),
237		}
238		for _, session := range source.Sessions {
239			payload.Sessions = append(payload.Sessions, fingerprintSession{
240				SessionID:        session.SessionID,
241				LatestCheckpoint: session.LatestCheckpoint,
242				Branch:           session.Branch,
243				TranscriptPath:   session.TranscriptPath,
244			})
245		}
246		data, err := json.Marshal(payload)
247		if err != nil {
248			return ""
249		}
250		sum := sha256.Sum256(data)
251		return "sha256:" + hex.EncodeToString(sum[:])
252	}
