861	func historyRecordQueryScore(record historyRecord, query string) int {
862		score := 0
863		if historyRecordMatchesQuery(record, query) {
864			score += 200
865		}
866		terms := historyQueryTerms(query)
867		identifiers := historyIdentifierQueryTerms(query)
868		if len(terms) == 0 && len(identifiers) == 0 {
869			return score
870		}
871		recordText := normalizeHistorySearchText(record.Summary + " " + strings.Join(record.Terms, " ") + " " + record.Path)
872		recordRaw := strings.ToUpper(record.Summary + " " + strings.Join(record.Terms, " ") + " " + record.Path)
873		recordTerms := normalizeHistorySearchText(strings.Join(record.Terms, " "))
874		matches := 0
875		for _, term := range terms {
876			if strings.Contains(recordText, term) {
877				matches++
878				score += 10
879				if strings.Contains(recordTerms, term) {
880					score += 5
881				}
882			}
883		}
884		identifierMatches := 0
885		for _, identifier := range identifiers {
886			if strings.Contains(recordRaw, identifier) {
887				identifierMatches++
888				score += 90
889			}
890		}
891		effectiveMatches := matches + identifierMatches
892		requiredTermCount := len(terms)
893		if requiredTermCount == 0 {
894			requiredTermCount = len(identifiers)
895		}
896		if effectiveMatches < historyRequiredQueryMatches(requiredTermCount) {
897			if score < 200 {
898				return 0
899			}
900			return score + historyKindRank(record.Kind)
901		}
902		score += effectiveMatches * 2
903		if len(terms) > 0 && matches >= len(terms) {
904			score += 30
905		}
906		score += historyRecordEvidenceScore(record, matches, identifierMatches)
907		score += historyKindRank(record.Kind)
908		return score
909	}
