911	func historyRecordEvidenceScore(record historyRecord, termMatches, identifierMatches int) int {
912		text := record.Summary + " " + strings.Join(record.Terms, " ") + " " + record.Path
913		lower := strings.ToLower(text)
914		score := 0
915		pathLower := strings.ToLower(record.Path)
916		if pathLower == "manifest.json" || strings.HasPrefix(pathLower, "seed/") {
917			score -= 200
918		}
919		if record.Kind == "code_fact" {
920			score += 35
921		}
922		if containsAny(lower, "diff --git", "+++ b/", "--- a/", "@@", "apply_patch", "unified_diff") {
923			score += 40
924		}
925		if containsAny(lower, "packages/", "internal/", "cmd/", "src/", "apps/", ".go", ".ts", ".tsx", ".js", ".py", ".rs") {
926			score += 20
927		}
928		if containsAny(lower, "metadata.step", "invalid_type", "metadata values must be strings", "metadata value") {
929			score += 80
930		}
931		if containsAny(lower, "stopped chaining", "self-contained perception", "self-contained browser", "previous_response_id") &&
932			containsAny(lower, "agentic", "browser", "chrome") {
933			score += 90
934		}
935		if containsAny(lower, "openai docs", "responses api supports", "same-thread continuity", "conversations api") &&
936			!containsAny(lower, "agentic", "browser", "chrome") {
937			score -= 60
938		}
939		if identifierMatches > 0 {
940			score += 20 * identifierMatches
941			if containsAny(lower, "diff --git", "+++ b/", "apply_patch", "unified_diff") {
942				score += 25
943			}
944		}
945		if termMatches > 1 && containsAny(lower, "test", "validation", "regression", "contract", "invariant") {
946			score += 12
947		}
948		if containsAny(lower, "start by running:", "entire doctor", "entire status --detailed", "entire session current", "entire checkpoint list") {
949			score -= 120
950		}
951		if record.Kind == "tool_call" && !containsAny(lower, "apply_patch", "diff --git", "unified_diff") {
952			score -= 20
953		}
954		if len(record.Summary) > 2500 && !containsAny(lower, "diff --git", "+++ b/", "apply_patch", "unified_diff") {
955			score -= 25
956		}
957		return score
958	}
959	
960	func historyInspectKindPreference(queryKind, recordKind string) int {
961		switch queryKind {
962		case "architecture":
963			switch recordKind {
964			case "architecture":
965				return 120
966			case "decision":
967				return 80
968			case "learning":
969				return 40
970			default:
971				return 0
972			}
973		default:
974			return 0
975		}
976	}
977	
978	func historyRequiredQueryMatches(termCount int) int {
979		switch {
980		case termCount <= 1:
981			return 1
982		case termCount <= 3:
983			return 2
984		default:
985			return 3
986		}
987	}
988	
989	func historyKindRank(kind string) int {
990		switch kind {
991		case "decision":
992			return 40
993		case "architecture":
994			return 32
995		case "code_fact":
996			return 30
997		case "learning":
998			return 26
999		case "validation":
1000			return 18
1001		case "tool_call":
1002			return 4
1003		default:
1004			return 1
1005		}
1006	}
1007	
1008	func historyQueryTerms(query string) []string {
1009		normalized := normalizeHistorySearchText(query)
1010		seen := map[string]struct{}{}
1011		var terms []string
1012		for _, term := range strings.Fields(normalized) {
1013			if historyQueryStopword(term) {
1014				continue
1015			}
1016			if len(term) < 3 && !historyShortQueryTerm(term) {
1017				continue
1018			}
1019			if _, ok := seen[term]; ok {
1020				continue
1021			}
1022			seen[term] = struct{}{}
1023			terms = append(terms, term)
1024		}
1025		return terms
1026	}
1027	
1028	func historyIdentifierQueryTerms(query string) []string {
1029		seen := map[string]struct{}{}
1030		var terms []string
1031		for _, candidate := range strings.FieldsFunc(query, func(r rune) bool {
1032			return !(unicode.IsLetter(r) || unicode.IsDigit(r) || r == '_')
1033		}) {
1034			candidate = strings.Trim(candidate, "_")
1035			if candidate == "" {
1036				continue
1037			}
1038			upper := strings.ToUpper(candidate)
1039			if !strings.Contains(upper, "_") && !historyIdentifierLike(candidate) {
1040				continue
1041			}
1042			if historyQueryStopword(strings.ToLower(upper)) {
1043				continue
1044			}
1045			if _, ok := seen[upper]; ok {
1046				continue
1047			}
1048			seen[upper] = struct{}{}
1049			terms = append(terms, upper)
1050		}
1051		return terms
1052	}
1053	
1054	func historyIdentifierLike(candidate string) bool {
1055		if len(candidate) < 3 {
1056			return false
1057		}
1058		hasUpper := false
1059		hasLower := false
1060		hasDigit := false
1061		hasInternalUpper := false
1062		for i, r := range candidate {
1063			switch {
1064			case unicode.IsUpper(r):
1065				hasUpper = true
1066				if i > 0 {
1067					hasInternalUpper = true
1068				}
1069			case unicode.IsLower(r):
1070				hasLower = true
1071			case unicode.IsDigit(r):
1072				hasDigit = true
1073			}
1074		}
1075		if hasUpper && !hasLower {
1076			return true
1077		}
1078		if hasInternalUpper && hasLower {
1079			return true
1080		}
1081		return hasDigit && (hasUpper || hasLower)
1082	}
1083	
1084	func historyShortQueryTerm(term string) bool {
1085		switch term {
1086		case "go", "ci", "pr", "ui", "id", "lc":
1087			return true
1088		default:
1089			return false
1090		}
1091	}
1092	
1093	func historyQueryStopword(term string) bool {
1094		switch term {
1095		case "a", "an", "and", "are", "as", "at", "be", "been", "but", "by", "can",
1096			"current", "do", "does", "during", "existing", "for", "from", "has",
1097			"have", "how", "in", "into", "is", "it", "its", "keep", "local",
1098			"make", "must", "new", "not", "of", "on", "only", "or", "other",
1099			"previous", "prior", "preserve", "regression", "restore", "same",
1100			"should", "task", "that", "the", "then", "this", "to", "use",
1101			"when", "where", "with", "without":
1102			return true
1103		case "behavior", "before", "entire", "fix", "fresh", "parent", "run",
1104			"runs", "setting", "value", "values":
1105			return true
1106		default:
1107			return false
1108		}
1109	}
1110	
1111	func loadBrainHistoryIndex(brainDir string, source *historySourceManifest) (historyIndex, error) {
1112		if source == nil || source.IndexPath == "" {
1113			return historyIndex{}, errors.New("history index missing; run `entire brain refresh`")
1114		}
1115		clean, err := validateHistoryIndexPath(source.IndexPath)
1116		if err != nil {
1117			return historyIndex{}, err
1118		}
1119		if err := rejectSymlinkPathComponents(brainDir, clean); err != nil {
1120			return historyIndex{}, err
1121		}
1122		data, err := os.ReadFile(filepath.Join(brainDir, clean))
1123		if err != nil {
1124			return historyIndex{}, err
1125		}
1126		var index historyIndex
1127		if err := json.Unmarshal(data, &index); err != nil {
1128			return historyIndex{}, err
1129		}
1130		return index, nil
1131	}
1132	
1133	func validateHistoryIndexPath(indexPath string) (string, error) {
1134		clean := filepath.Clean(filepath.FromSlash(indexPath))
1135		cleanSlash := filepath.ToSlash(clean)
1136		if cleanSlash != indexPath {
1137			return "", fmt.Errorf("history index_path must be canonical: %s", indexPath)
1138		}
1139		if strings.HasPrefix(clean, ".."+string(filepath.Separator)) || filepath.IsAbs(clean) || cleanSlash != historyIndexPath {
1140			return "", fmt.Errorf("history index_path is unsafe: %s", indexPath)
1141		}
1142		return clean, nil
1143	}
